"use strict";
// Value origin for the Eclipse plugin: the VS Code analysis and its page, as one script for the plugin's browser.
// The modules are the VS Code files unchanged, each wrapped as the CommonJS module it is; a require outside this
// list is an error, not a stub, so a module that starts to need Node fails here and not in front of the reader.
const fs = require("node:fs");
const path = require("node:path");

const MODULES = ["abap-control", "call-graph", "value-origin-tokens", "value-origin-model", "value-origin", "value-origin-ace", "value-origin-formula",
  "value-origin-formula-html", "value-origin-points", "value-origin-view", "value-origin-open", "value-origin-demand", "value-origin-pipeline"];

function bundle(root = path.join(__dirname, "..")) {
  const parts = MODULES.map(name => {
    // vscode/abap-control.js only finds the statement rules with fs; the browser takes the rules file itself.
    const file = name === "abap-control" ? path.join(root, "org.vertex.abap.ui", "resources", "vertex-abap-control.js")
      : path.join(root, "vscode", name + ".js");
    const text = fs.readFileSync(file, "utf8");
    return JSON.stringify("./" + name) + ": function (module, exports, require) {\n" + text + "\n}";
  });
  return "// Generated by eclipse/prepare.js from vscode/" + MODULES.join(".js, vscode/") + ".js - edit those.\n"
    + "(function (root) {\n"
    // value-origin-formula.js reads process.env.DUMP for a debugging dump; there is no process in a browser.
    + "var process = { env: {} };\n"
    + "var modules = {\n" + parts.join(",\n") + "\n};\n"
    + "var cache = {};\n"
    + "function load(name) {\n"
    + "  if (!Object.prototype.hasOwnProperty.call(modules, name)) { throw new Error('Value origin in Eclipse has no module ' + name + '.'); }\n"
    + "  if (!cache[name]) { var module = { exports: {} }; cache[name] = module; try { modules[name](module, module.exports, load); } catch (error) { delete cache[name]; throw error; } }\n"
    + "  return cache[name].exports;\n"
    + "}\n"
    + "var origin = load('./value-origin'), ace = load('./value-origin-ace'), points = load('./value-origin-points'),\n"
    + "  view = load('./value-origin-view'), open = load('./value-origin-open'), pipeline = load('./value-origin-pipeline');\n"
    + "root.vertexOrigin = { analyze: origin.analyze, collect: pipeline.collect,\n"
    + "  variableAt: origin.variableAt,\n"
    + "  literalAt: origin.literalAt, locateTarget: ace.locateTarget, pathRows: points.pathRows,\n"
    + "  siteRows: points.siteRows, html: view.html, sourceLineIn: open.sourceLineIn, methodLine: open.methodLine };\n"
    + "})(typeof window !== 'undefined' ? window : this);\n";
}

module.exports = { bundle, MODULES };
